"""Rig UI for RIG_Operative: a self-contained script that is stored inside Operative.blend as the text block
`morphrig_ui.py` (registered on load) and adds the "MorphRig" tab to the 3D viewport sidebar.

install(rig, mesh) writes the text block and registers it for the running session.
"""
import bpy

TEXT_NAME = 'morphrig_ui.py'

UI_SCRIPT = r'''
# MorphRig rig UI - generated by source/generators/mr/rigui.py (edit there, the build rewrites this text block)
import bpy
import math
from mathutils import Vector, Matrix

RIG = "RIG_Operative"
MESH = "Operative"
TEAMS = {"A": ((0.0, 0.62, 1.0), 0.0), "B": ((1.0, 0.36, 0.02), 1.0)}
FINGERS = ("thumb", "index", "middle", "ring", "pinky")
FOOT_PROPS = ("roll", "bank", "heel_pivot", "toe_pivot", "toe_bend")
DEMO_PREFIX = "DEMO_"


def rig_object(context=None):
    ob = bpy.data.objects.get(RIG)
    return ob


def _upd():
    bpy.context.view_layer.update()


def _set_matrix(rig, bone, M):
    rig.pose.bones[bone].matrix = M
    _upd()


def _key_if_auto(rig, names, props=()):
    sc = bpy.context.scene
    if not sc.tool_settings.use_keyframe_insert_auto:
        return
    for n in names:
        pb = rig.pose.bones[n]
        pb.keyframe_insert("location")
        pb.keyframe_insert("rotation_quaternion")
    for (n, p) in props:
        rig.pose.bones[n].keyframe_insert('["%s"]' % p)


def _perp(v, axis):
    return v - axis * v.dot(axis)


def _pole(rig, a, mid_joint, b, dist, rest_names):
    """Pole target position for the chain a - mid_joint - b. The IK constraints carry a pole angle that was
    calibrated on the rest pose (the rest pole is not exactly in the plane of the rest limb), so the same signed
    angle between the limb plane and the pole direction is reproduced here."""
    B = rig.data.bones
    ra, rm, rb, rp = (B[n].head_local for n in rest_names)
    rax = (rb - ra).normalized()
    re, rpd = _perp(rm - ra, rax), _perp(rp - ra, rax)
    phi = 0.0
    if re.length > 1e-6 and rpd.length > 1e-6:
        re.normalize()
        rpd.normalize()
        phi = math.atan2(rax.dot(re.cross(rpd)), re.dot(rpd))
    ax = (b - a).normalized()
    d = _perp(mid_joint - a, ax)
    if d.length < 1e-5:
        d = ax.orthogonal()
    d.normalize()
    d = Matrix.Rotation(phi, 3, ax) @ d
    return (a + b) * 0.5 + d * dist


def reset_pose(rig, selected_only=False):
    for pb in rig.pose.bones:
        if selected_only and not pb.bone.select:
            continue
        pb.location = (0, 0, 0)
        pb.rotation_quaternion = (1, 0, 0, 0)
        pb.rotation_euler = (0, 0, 0)
        pb.scale = (1, 1, 1)
        for k in pb.keys():
            if k.startswith("_"):
                continue
            try:
                pb[k] = pb.id_properties_ui(k).as_dict().get("default", 0.0)
            except Exception:
                pass
    _upd()


def snap_arm(rig, side, to_ik):
    P = rig.pose.bones
    L = lambda n: n + "_" + side
    if to_ik:
        # IK controls take over the current (FK) arm
        sh = P[L("upperarm")].head.copy()
        el = P[L("lowerarm")].head.copy()
        wr = P[L("hand")].head.copy()
        M = P[L("hand")].matrix.copy()
        _set_matrix(rig, L("hand_ik"), M)
        pm = P[L("elbow_pole")].matrix.copy()
        pm.translation = _pole(rig, sh, el, wr, 0.45, (L("upperarm"), L("lowerarm"), L("hand"), L("elbow_pole")))
        _set_matrix(rig, L("elbow_pole"), pm)
        P[L("hand_ik")]["arm_ik"] = 1.0
        _key_if_auto(rig, [L("hand_ik"), L("elbow_pole")], [(L("hand_ik"), "arm_ik")])
    else:
        mats = [P[L(n)].matrix.copy() for n in ("upperarm", "lowerarm", "hand")]
        for n, M in zip(("upperarm_fk", "lowerarm_fk", "hand_fk"), mats):
            _set_matrix(rig, L(n), M)
        P[L("hand_ik")]["arm_ik"] = 0.0
        _key_if_auto(rig, [L("upperarm_fk"), L("lowerarm_fk"), L("hand_fk")], [(L("hand_ik"), "arm_ik")])
    rig.update_tag()
    _upd()


def snap_leg(rig, side, to_ik):
    P = rig.pose.bones
    B = rig.data.bones
    L = lambda n: n + "_" + side
    if to_ik:
        hip = P[L("thigh")].head.copy()
        kn = P[L("calf")].head.copy()
        an = P[L("foot")].head.copy()
        foot = P[L("foot")].matrix.copy()
        ball = P[L("ball")].matrix.copy()
        fik = P[L("foot_ik")]
        for p in FOOT_PROPS:
            fik[p] = 0.0
        # the control keeps its rest offset to the foot bone
        off = B[L("foot")].matrix_local.inverted() @ B[L("foot_ik")].matrix_local
        _set_matrix(rig, L("foot_ik"), foot @ off)
        pm = P[L("knee_pole")].matrix.copy()
        pm.translation = _pole(rig, hip, kn, an, 0.55, (L("thigh"), L("calf"), L("foot"), L("knee_pole")))
        _set_matrix(rig, L("knee_pole"), pm)
        # toe: express the remaining ball rotation with the toe bend property (45 degrees per unit)
        rel = (foot.inverted() @ ball)
        rest = (B[L("foot")].matrix_local.inverted() @ B[L("ball")].matrix_local)
        ang = (rest.inverted() @ rel).to_euler("XYZ").x
        fik["toe_bend"] = max(-2.0, min(2.0, ang / math.radians(45.0)))
        fik["leg_ik"] = 1.0
        _key_if_auto(rig, [L("foot_ik"), L("knee_pole")], [(L("foot_ik"), p) for p in FOOT_PROPS + ("leg_ik",)])
    else:
        mats = [P[L(n)].matrix.copy() for n in ("thigh", "calf", "foot", "ball")]
        for n, M in zip(("thigh_fk", "calf_fk", "foot_fk", "toe_fk"), mats):
            _set_matrix(rig, L(n), M)
        P[L("foot_ik")]["leg_ik"] = 0.0
        _key_if_auto(rig, [L("thigh_fk"), L("calf_fk"), L("foot_fk"), L("toe_fk")], [(L("foot_ik"), "leg_ik")])
    rig.update_tag()
    _upd()


class MORPHRIG_OT_reset(bpy.types.Operator):
    bl_idname = "morphrig.reset_pose"
    bl_label = "Reset Pose"
    bl_description = "Return every control (or the selected ones) to the rest pose and restore property defaults"
    bl_options = {"REGISTER", "UNDO"}
    selected_only: bpy.props.BoolProperty(default=False)

    def execute(self, context):
        rig = rig_object()
        if rig is None:
            return {"CANCELLED"}
        reset_pose(rig, self.selected_only)
        return {"FINISHED"}


class MORPHRIG_OT_snap(bpy.types.Operator):
    bl_idname = "morphrig.snap"
    bl_label = "IK/FK Snap"
    bl_description = "Switch a limb between IK and FK without changing its pose"
    bl_options = {"REGISTER", "UNDO"}
    limb: bpy.props.EnumProperty(items=[("ARM", "Arm", ""), ("LEG", "Leg", "")])
    side: bpy.props.EnumProperty(items=[("l", "Left", ""), ("r", "Right", "")])
    to_ik: bpy.props.BoolProperty(default=True)

    def execute(self, context):
        rig = rig_object()
        if rig is None:
            return {"CANCELLED"}
        (snap_arm if self.limb == "ARM" else snap_leg)(rig, self.side, self.to_ik)
        return {"FINISHED"}


class MORPHRIG_OT_scale(bpy.types.Operator):
    bl_idname = "morphrig.global_scale"
    bl_label = "Global Scale"
    bl_description = "Uniform scale of the whole rig through the root control (1.0 = 1.80 m)"
    bl_options = {"REGISTER", "UNDO"}
    scale: bpy.props.FloatProperty(default=1.0, min=0.1, max=10.0)

    def execute(self, context):
        rig = rig_object()
        if rig is None:
            return {"CANCELLED"}
        rig.pose.bones["root"].scale = (self.scale,) * 3
        return {"FINISHED"}


class MORPHRIG_OT_team(bpy.types.Operator):
    bl_idname = "morphrig.team"
    bl_label = "Team Variant"
    bl_description = "Team accent variant: A = cyan / chevron / solid trim, B = amber / ring / dashed trim"
    bl_options = {"REGISTER", "UNDO"}
    team: bpy.props.EnumProperty(items=[("A", "Team A", ""), ("B", "Team B", "")])

    def execute(self, context):
        col, icon = TEAMS[self.team]
        for ob in bpy.data.objects:
            if ob.type == "MESH" and "team_color" in ob:
                ob["team_color"] = col
                ob["team_icon"] = icon
                ob["team"] = self.team
                ob.update_tag()
        return {"FINISHED"}


class MORPHRIG_OT_demo(bpy.types.Operator):
    bl_idname = "morphrig.demo_pose"
    bl_label = "Demo Pose"
    bl_description = "Apply one of the deformation test poses"
    bl_options = {"REGISTER", "UNDO"}
    name: bpy.props.StringProperty()

    def execute(self, context):
        rig = rig_object()
        act = bpy.data.actions.get(DEMO_PREFIX + self.name)
        if rig is None or act is None:
            return {"CANCELLED"}
        reset_pose(rig)
        rig.pose.apply_pose_from_action(act, evaluation_time=0.0)
        _upd()
        return {"FINISHED"}


class MORPHRIG_OT_bake_cable(bpy.types.Operator):
    bl_idname = "morphrig.bake_cable"
    bl_label = "Bake Cable"
    bl_description = "Simulate the data cable for the active action and key the cable controls (delete their keys to animate by hand)"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        import os, sys
        rig = rig_object()
        ad = rig.animation_data if rig else None
        if not ad or not ad.action:
            self.report({"ERROR"}, "Assign an action to the rig first")
            return {"CANCELLED"}
        gen = bpy.path.abspath("//generators")
        if gen not in sys.path:
            sys.path.insert(0, gen)
        try:
            from mr import secondary
        except Exception as e:
            self.report({"ERROR"}, "generators not found next to the .blend: %s" % e)
            return {"CANCELLED"}
        a0, a1 = ad.action.frame_range
        loop = ad.action.get("loop", False)
        secondary.bake_cable(rig, ad.action, ad.action_slot, int(round(a1)), loop=bool(loop))
        return {"FINISHED"}


class MORPHRIG_PT_main(bpy.types.Panel):
    bl_label = "MorphRig"
    bl_idname = "MORPHRIG_PT_main"
    bl_space_type = "VIEW_3D"
    bl_region_type = "UI"
    bl_category = "MorphRig"

    def draw(self, context):
        lay = self.layout
        rig = rig_object()
        if rig is None:
            lay.label(text="RIG_Operative not found")
            return
        P = rig.pose.bones
        row = lay.row(align=True)
        row.operator("morphrig.reset_pose", text="Reset Pose", icon="LOOP_BACK").selected_only = False
        row.operator("morphrig.reset_pose", text="Selected").selected_only = True
        row = lay.row(align=True)
        row.prop(P["root"], "scale", index=0, text="Global Scale")
        for s in (0.5, 1.0, 2.0):
            row.operator("morphrig.global_scale", text="%gx" % s).scale = s
        row = lay.row(align=True)
        row.operator("morphrig.team", text="Team A").team = "A"
        row.operator("morphrig.team", text="Team B").team = "B"


class _Sub:
    bl_space_type = "VIEW_3D"
    bl_region_type = "UI"
    bl_category = "MorphRig"
    bl_parent_id = "MORPHRIG_PT_main"
    bl_options = {"DEFAULT_CLOSED"}

    @classmethod
    def poll(cls, context):
        return rig_object() is not None


class MORPHRIG_PT_limbs(_Sub, bpy.types.Panel):
    bl_label = "Arms and Legs (IK / FK)"
    bl_idname = "MORPHRIG_PT_limbs"
    bl_options = set()

    def draw(self, context):
        lay = self.layout
        P = rig_object().pose.bones
        for limb, ctl, prop, label in (("ARM", "hand_ik", "arm_ik", "Arm"), ("LEG", "foot_ik", "leg_ik", "Leg")):
            for side, sname in (("l", "L"), ("r", "R")):
                box = lay.box()
                pb = P[ctl + "_" + side]
                row = box.row(align=True)
                row.prop(pb, '["%s"]' % prop, text="%s %s  FK <> IK" % (label, sname), slider=True)
                row = box.row(align=True)
                op = row.operator("morphrig.snap", text="Snap to IK")
                op.limb, op.side, op.to_ik = limb, side, True
                op = row.operator("morphrig.snap", text="Snap to FK")
                op.limb, op.side, op.to_ik = limb, side, False
                if limb == "LEG":
                    col = box.column(align=True)
                    for p in FOOT_PROPS:
                        col.prop(pb, '["%s"]' % p, slider=True)


class MORPHRIG_PT_hands(_Sub, bpy.types.Panel):
    bl_label = "Hands"
    bl_idname = "MORPHRIG_PT_hands"

    def draw(self, context):
        lay = self.layout
        P = rig_object().pose.bones
        for side, sname in (("l", "Left hand"), ("r", "Right hand (cybernetic)")):
            pb = P["fingers_" + side]
            box = lay.box()
            box.label(text=sname)
            col = box.column(align=True)
            col.prop(pb, '["fist"]', slider=True)
            col.prop(pb, '["spread"]', slider=True)
            for f in FINGERS:
                col.prop(pb, '["curl_%s"]' % f, slider=True)


class MORPHRIG_PT_face(_Sub, bpy.types.Panel):
    bl_label = "Face"
    bl_idname = "MORPHRIG_PT_face"

    def draw(self, context):
        lay = self.layout
        pb = rig_object().pose.bones["face"]
        col = lay.column(align=True)
        for p in ("eyes_track", "head_track", "lid_follow"):
            col.prop(pb, '["%s"]' % p, slider=True)
        keys = [k for k in pb.keys() if not k.startswith("_")]
        box = lay.box()
        box.label(text="Expression presets")
        col = box.column(align=True)
        for k in keys:
            if k.startswith("expr_"):
                col.prop(pb, '["%s"]' % k, text=k[5:], slider=True)
        box = lay.box()
        box.label(text="Visemes")
        col = box.column(align=True)
        for k in keys:
            if k.startswith("vis_"):
                col.prop(pb, '["%s"]' % k, text=k[4:], slider=True)
        box = lay.box()
        box.label(text="Controls")
        col = box.column(align=True)
        for k in keys:
            if not k.startswith(("expr_", "vis_")) and k not in ("eyes_track", "head_track", "lid_follow"):
                col.prop(pb, '["%s"]' % k, slider=True)


class MORPHRIG_PT_extras(_Sub, bpy.types.Panel):
    bl_label = "Props, Secondary Motion, Demo Poses"
    bl_idname = "MORPHRIG_PT_extras"

    def draw(self, context):
        lay = self.layout
        P = rig_object().pose.bones
        box = lay.box()
        box.label(text="Props (hold in hand)")
        for prop in ("prop_cell", "prop_cell_spare", "prop_beacon"):
            row = box.row(align=True)
            row.label(text=prop)
            for h in ("hold_hand_l", "hold_hand_r"):
                if h in P[prop]:
                    row.prop(P[prop], '["%s"]' % h, text=h[-1].upper(), slider=True)
        box.prop(P["blade_l"], "location", index=1, text="Blade extend (m)")
        box = lay.box()
        box.label(text="Secondary")
        box.prop(P["cog"], '["breath"]', slider=True)
        box.operator("morphrig.bake_cable", icon="PHYSICS")
        box = lay.box()
        box.label(text="Deformation test poses")
        col = box.column(align=True)
        for act in bpy.data.actions:
            if act.name.startswith(DEMO_PREFIX):
                col.operator("morphrig.demo_pose", text=act.name[len(DEMO_PREFIX):].replace("_", " ")).name = act.name[len(DEMO_PREFIX):]


CLASSES = (MORPHRIG_OT_reset, MORPHRIG_OT_snap, MORPHRIG_OT_scale, MORPHRIG_OT_team, MORPHRIG_OT_demo, MORPHRIG_OT_bake_cable,
           MORPHRIG_PT_main, MORPHRIG_PT_limbs, MORPHRIG_PT_hands, MORPHRIG_PT_face, MORPHRIG_PT_extras)


def register():
    for c in CLASSES:
        try:
            bpy.utils.register_class(c)
        except ValueError:
            bpy.utils.unregister_class(c)
            bpy.utils.register_class(c)


def unregister():
    for c in reversed(CLASSES):
        try:
            bpy.utils.unregister_class(c)
        except Exception:
            pass


if __name__ == "__main__":
    register()
'''


def install(run=True):
    """Store the UI script in the .blend (auto-registered on load) and register it now."""
    txt = bpy.data.texts.get(TEXT_NAME)
    if txt is None:
        txt = bpy.data.texts.new(TEXT_NAME)
    txt.clear()
    txt.write(UI_SCRIPT)
    txt.use_module = True
    if run:
        ns = {'__name__': '__main__'}
        exec(compile(UI_SCRIPT, TEXT_NAME, 'exec'), ns)
        return ns
    return None
